if(x.a>0.6)out.push('{b}は呼吸を数えて平静を保とうとしたが、途中で数えるのをやめた。','{b}は頭の中で何かを考えようとして、何も考えられなくなった。');
if(x.np>0.6)out.push('{b}は{a}の背中を抱き寄せて、「大丈夫だから｜大丈夫だ｜大丈夫ですから」と囁いた。','{b}は{a}の髪を撫でながら、何度も名前を呼んだ。');
var X=L.REACT_X||{};
['ac','cp','fc','a','np'].forEach(function(k){if(x[k]>0.6&&X[k])out.push.apply(out,X[k]);});
