P.forEach(function(c){c.stress=HK.clamp(c.stress+ctx.env.pressure/100*12+4,0,100);});
if(P.length===2)ctx.mod2(P[0],P[1],{trust:2.5,att:ctx.flags.romantic?2:0.5,ten: -1},{trust:2.5,att:ctx.flags.romantic?2:0.5,ten: -1});
