X.ROUND2=L('三人は、もう一度身を寄せ合った。今度は、誰も照れなかった。|二回目は、一回目より自然だった。三人は、もう誰が先に触れるかで迷わなかった。|休憩もそこそこに、{x}がまた二人の手を引いた。|三人は水を回し飲みしてから、また互いに手を伸ばした。|{h}が「もう一回｜もう一回だ｜もう一回しましょう」と言った。言い終わる前に、{x}と{y}の手が伸びてきた。|二回目は、一回目とは違う組み合わせから始まった。三人は、もう形にこだわらなかった。');
X.OPEN={
auto:L('{x}と{y}の視線が、同時に{h}に向いた。三人は紙の但し書きを読み返して、顔を見合わせた。{h}「……三人でなら、一回で済む｜＝｜……三人でなら、一回で済みます」――誰も、反対しなかった。|{x}が{h}の隣に座り、少し遅れて{y}が反対側に座った。{h}は両側の体温に挟まれて、小さく息を吐いた。{h}「……分かった。三人で｜……分かった。三人でだ｜……分かりました。三人でしましょう」|白い部屋に、長い沈黙が続いた。それを破ったのは{y}だった。{y}「誰か一人を選ぶとか、もう、やめよう｜誰か一人を選ぶのは、もう、やめよう｜誰か一人を選ぶとか、もう、やめましょう」{x}が頷き、{h}が二人の手を取った。|{h}は扉の紙を指でなぞって、但し書きの一文で止めた。{h}「ここ。……三人なら、全員で出られる｜ここだ。……三人なら、全員で出られる｜ここです。……三人なら、全員で出られます」{x}と{y}は顔を見合わせ、それから{h}を見た。|{h}はベッドの真ん中に座って、両側を軽く叩いた。{h}「二人とも、来て｜二人とも、来い｜二人とも、来てください」{x}と{y}は一瞬ためらって、それから同時に動いた。|三人で閉じ込められて、何時間も経っていた。誰と誰が、という線引きは、もうどうでもよくなっていた。{x}が{h}の手を取り、{y}がその上に手を重ねた。|{y}「三人で、っていうのは……」言いかけた{y}の言葉を、{x}が引き取った。{x}「あり、だと思う｜＝｜あり、だと思います」――{h}は少し笑って、頷いた。|三人は紙の但し書きを、何度も読んだ。{h}「誰か一人を置いていくのは、嫌｜誰か一人を置いていくのは、嫌だ｜誰か一人を置いていくのは、嫌です」――それが答えだった。'),
join:L('{x}と{y}が先に始めていた。{h}は壁際で背を向けていたが、二人の声は耳を塞いでも届いた。やがて{h}は立ち上がった。|{x}と{y}の体が重なるのを、{h}は部屋の隅から見ていた。見ているうちに、{h}の息も上がっていた。{y}が気づいて、黙って手を差し伸べた。|二人が終わりかけたとき、{h}がベッドの端に座った。{h}「……私も、数えてもらえる？｜……私も、数えてもらえるか？｜……私も、数えてもらえますか？」{x}は笑って、{h}の手を引いた。|{x}は{y}を抱きながら、部屋の隅の{h}に目をやった。{x}「{h}も、こっち｜{h}も、こっちへ来い｜{h}も、こっちへ来てください」――{h}は少し迷ってから、服のボタンに手をかけた。'),
aphro:L('媚薬の熱は、三人全員に回っていた。誰が最初に手を伸ばしたのかは、もう誰も覚えていない。|{h}の呼吸が浅く、肌は熱を帯びていた。{x}と{y}も同じだった。三人の視線が絡まった瞬間、理性の糸が同時に切れた。|{h}「もう、無理……｜もう、無理だ……｜もう、無理です……」媚薬に浮かされた{h}の声に、{x}と{y}は同時に動いた。止める者は、この部屋にはいなかった。|媚薬の甘い匂いが、白い部屋を満たしていた。三人は言葉もなく、熱に押されるように身を寄せた。正気は、どこにも残っていなかった。')
};
(function(){
var add=function(arr,s){Array.prototype.push.apply(arr,L(s));};
add(X.MAIN.sandwich,'{t}は{m}を後ろから抱きすくめ、{m}は{u}を胸の下に抱き込んだ。ベッドが深く沈み、{t}が動くたびに、その揺れが{m}を通って{u}まで届いた。|{m}は前の{u}と後ろの{t}に挟まれて、どちらに意識を向ければいいのか分からなくなった。{u}の甘い声と{t}の荒い息が、両方の耳を塞いでいた。');
add(X.MAIN.twoOne,'{t}と{m}は、{u}を挟んで向かい合った。前からは口づけが、後ろからは揺さぶりが、休む間もなく{u}に降ってきた。|{u}は{t}の腕にしがみつきながら、{m}の手に腰を支えられていた。二人がかりで愛されて、{u}の声はだんだん言葉にならなくなっていった。');
add(X.MAIN.oneTwo,'{t}は{m}を抱きながら、空いた手で{u}の髪を撫でていた。自分の番を待つ{u}の目が、熱っぽく{t}を追っていた。|{t}は二人を交互に抱き寄せ、どちらにも同じだけの時間をかけた。{m}と{u}は、順番が回ってくるたびに、前より早く蕩けた。');
add(X.MAIN_FF.sandwich,'{m}は{u}の胸の先を唇で含みながら、指で{u}の脚のあいだを撫でた。その{m}の内腿を、後ろから{t}の舌がゆっくりとなぞり上げた。|{t}の指が{m}の中を探り、{m}の指が{u}の中を探った。同じ速さで動く指先に、吐息が重なっていった。');
add(X.MAIN_FF.twoOne,'{t}は{u}の脚のあいだに顔を埋め、{m}は後ろから{u}を抱きしめて両胸を包んだ。上と下から同時にほどかれて、{u}は{m}の肩に頭を預けた。|{t}と{m}は、{u}の左右の内腿に同時に口づけた。それから二人は交互に、{u}のいちばん敏感なところへ舌を伸ばした。');
add(X.MAIN_FF.oneTwo,'{t}は{m}の脚のあいだに舌を這わせながら、指を伸ばして隣の{u}を撫でた。二人の甘い声が、交互に、それから同時に上がった。|{m}と{u}は並んで横たわり、{t}の指を一本ずつ握った。{t}はその手を握り返しながら、二人の熱いところを交互にほどいていった。');
add(X.CLIMAX,'誰の声が最後だったのか、誰にも分からなかった。気づいたときには、みんな息を切らして天井を見上げていた。|三人は互いの体にしがみついたまま、波が引くのを待った。誰かの手が、誰かの背中をずっと撫でていた。|一人が達すると、その震えがすぐ隣に伝わって、残りの二人も続けざまに崩れた。白い部屋に、荒い息だけが残った。|三人は額を寄せ合ったまま、ほとんど同時に達した。互いの汗が混ざって、誰のものか分からなかった。');
var C=function(id){return X.CLIMAX_X.filter(function(o){return o.id===id;})[0];};
var c2=C('c_two'),cm=C('c_mid'),c1=C('c_one'),co=C('c_open'),cs=C('c_shy'),cl=C('c_love'),ch=C('c_lovehub');
if(c2)add(c2.t,'{u}は{t}と{m}の腕の中で、何度も小さく達した。二人は顔を見合わせて、{u}の震えが収まるまで両側から抱きしめていた。|{u}が{t}の名前を、それから{m}の名前を呼んで達した。二人は同時に{u}の額に口づけ、それから自分たちも崩れた。');
if(cm)add(cm.t,'{m}は前と後ろから押し寄せる熱に耐えきれず、声を上げて達した。その震えが{u}にも{t}にも伝わり、三人は折り重なるように崩れた。|{u}が先に崩れ、その締めつけで{m}が、{m}の震えで{t}が、順番に達していった。息が整うまで、誰も動かなかった。');
if(c1)add(c1.t,'{t}は{m}と{u}を交互に追い上げ、二人がほとんど同時に達したのを見届けてから、自分も二人の間に崩れ落ちた。|{m}と{u}は手を握り合ったまま、{t}の腕の中で続けて達した。{t}は二人の髪を撫でながら、最後に自分も果てた。');
if(co)add(co.t,'{s}は二人の名前を交互に呼びながら、遠慮なく声を上げて達した。{p}と{q}は顔を見合わせ、満足そうに笑った。|{s}は果てたあと、「もう一回｜もう一回だ｜もう一回しましょう」と息も整わないうちに笑った。二人は呆れながら、それでも{s}を抱き寄せた。');
if(cs)add(cs.t,'{s}は二人の腕に顔を隠したまま、震えるように達した。小さくこぼれた声を、{p}も{q}も聞き逃さなかった。|{s}は唇を噛んで声を殺し、それでも最後に一度だけ、二人の名前を呼んで果てた。');
if(cl)add(cl.t,'三人は指を絡め合ったまま、同じ波に呑まれていった。果てたあとも、誰も手を離そうとしなかった。|{h}が達したのを合図に、{x}と{y}も続いた。三人はいつものように、互いの名前を順番に呼び合った。');
if(ch)add(ch.t,'{h}は{x}と{y}の手を両方握ったまま、深く果てた。二人は{h}の両頬に同時に口づけて、顔を見合わせて笑った。');
add(X.MAIN.sandwich,'{t}は{m}の腰を抱き寄せ、耳元で囁いた。{t}「前も後ろも、逃げ場はないよ｜前も後ろも、逃げ場はないぞ｜前も後ろも、逃げ場はありませんよ」――{m}が{u}の奥へ沈むのと同時に、{t}も{m}を深く貫いた。|{t}は{m}の背中に胸を重ね、{m}の肩越しに{u}の顔を覗き込んだ。{t}「二人とも、いい顔してる｜二人とも、いい顔をしている｜お二人とも、いいお顔をしていますね」――{t}が一度突き上げるたびに、その揺れが{m}を通って{u}の奥まで届いた。');
add(X.MAIN.twoOne,'{t}は{u}の脚を抱え上げて深く沈み、{m}に目配せした。{t}「次は、あなたの番だよ｜次は、あなたの番だ｜次は、あなたの番です」――{t}と{m}が交代するたびに、{u}はまた最初から蕩かされていった。|{t}は後ろから{u}を貫きながら、{u}の顎を持ち上げて{m}のほうへ向かせた。{t}「ほら、ちゃんと顔を見せてあげて｜ほら、ちゃんと顔を見せてやれ｜ほら、ちゃんとお顔を見せてあげてください」――{m}に唇を塞がれて、{u}の声は二人のあいだでくぐもった。');
add(X.MAIN.oneTwo,'{t}は{m}の奥まで沈んだまま、隣の{u}の頬に手を伸ばした。{t}「待たせてごめんね。すぐ行くから｜待たせてすまない。すぐ行く｜お待たせしてすみません。すぐに行きますから」――{u}はその指先に口づけて、自分の番を待った。|{t}は{m}と{u}を並べて寝かせ、交互に奥を突いた。{t}「二人とも、声を合わせて｜二人とも、声を合わせろ｜お二人とも、声を合わせてください」――言われたとおりに重なった二人の声に、{t}の動きが速くなった。');
add(X.MAIN.ring,'三人は輪になって繋がった。{t}「誰が先に音を上げるか、競争しよう｜誰が先に音を上げるか、競争だ｜誰が先に音を上げるか、競争しましょう」――{t}が{m}を、{m}が{u}を、{u}が{t}を、同じ速さで追い上げていった。');
add(X.MAIN_FF.sandwich,'{t}は{m}の背中に胸を重ね、{m}の指が{u}の中で動くのに合わせて、後ろから{m}の脚のあいだを撫でた。{t}「止めないで。そのまま、二人で｜止めるな。そのまま、二人でだ｜止めないでください。そのまま、お二人で」――吐息が、一つに重なっていった。');
add(X.MAIN_FF.twoOne,'{t}は{u}の脚のあいだに指を沈め、{m}は{u}の胸を唇で包んだ。{t}「力を抜いて。二人で、ちゃんと気持ちよくするから｜力を抜け。二人で、ちゃんと気持ちよくする｜力を抜いてください。二人で、ちゃんと気持ちよくしますから」――{u}は両側からの熱に、すぐに何も考えられなくなった。');
add(X.MAIN_FF.oneTwo,'{t}は{m}と{u}のあいだに膝をつき、両手で二人の熱いところを同時にほどいた。{t}「どっちが先に、声を出すかな｜どっちが先に、声を出すか｜どちらが先に、声を出しますか」――答えの代わりに、甘い声が重なった。');
add(X.MAIN_FF.ring,'三人は輪になって、それぞれの指を隣の人の熱いところへ伸ばした。{t}「誰が先に音を上げるか、競争しよう｜誰が先に音を上げるか、競争だ｜誰が先に音を上げるか、競争しましょう」――三人の指が、同じ速さで動きはじめた。');
add(X.AFTER,'終わったあと、三人は一枚の毛布を取り合いながら笑った。結局、真ん中の一人だけがちゃんと包まれていた。|三人は並んで寝転がり、誰からともなく天井の白さについて文句を言った。笑い声が、少しずつ寝息に変わっていった。|終わったあと、一人が水を汲みに立ち、紙コップを持って戻ってきた。三人は黙って乾杯の真似をした。');
})();
X.WATCH={
proud:L('{h}越しに、{b}と目が合った。{a}は口の端を上げた。{a}「よそ見してる暇があるなら、{h}だけ見てなよ｜よそ見している暇があるなら、{h}だけ見ていろ｜よそ見をしている暇があるなら、{h}だけを見ていてください」|{a}は{b}のほうを一度だけ見て、それきり{h}から目を離さなかった。{a}「そっちには譲らない｜そちらには譲らない｜そちらには譲りません」'),
stern:L('{a}は{b}に短く目で合図をした。それ以上は何も言わず、{h}だけに向き直った。|{h}の向こうの{b}に、{a}は低く釘を刺した。{a}「……{b}、{h}に無理させないでね｜……{b}、{h}に無理をさせるな｜……{b}、{h}に無理をさせないでください」'),
tsun:L('{a}は、{h}の向こうで顔を上気させている{b}をちらりと見て、すぐにそっぽを向いた。{a}「……べつに、見てないし｜……べつに、見ていない｜……べつに、見ていません」|{a}「{b}ばっかり、ずるい｜{b}ばかり、ずるいぞ｜{b}ばかり、ずるいです」――小声で文句を言いながらも、{a}は{h}から目を離さなかった。'),
gentle:L('{a}は、{h}の向こうの{b}に小さく笑いかけた。{a}「大丈夫？　ゆっくりでいいよ｜大丈夫か。ゆっくりでいい｜大丈夫ですか？　ゆっくりでいいですよ」|{b}の息が上がっているのに気づいて、{a}は{h}越しに声をかけた。{a}「{b}も、無理しないで｜{b}も、無理はするな｜{b}も、無理はしないでください」'),
devoted:L('{a}は{b}のほうを見て、静かに頷いた。いまは二人とも、{h}のためにここにいる――{a}には、それで十分だった。|{a}は、{h}を挟んだ向こうの{b}を気づかうように見た。{a}「苦しくない？｜苦しくないか｜苦しくありませんか？」{b}は、小さく首を横に振った。'),
cool:L('{a}は{h}越しに{b}を一瞥した。{a}「……見てる暇があるなら、集中して｜……見ている暇があるなら、集中しろ｜……見ている暇があるなら、集中してください」|{a}は{b}と目が合っても、表情ひとつ変えなかった。ただ、{h}に向ける吐息だけが、少しずつ熱を帯びていった。'),
free:L('{a}は{h}の向こうの{b}に、にっと笑ってみせた。{a}「ねえ{b}、いい顔してる｜おい{b}、いい顔をしている｜ねえ{b}、いい顔をしていますね」{b}は真っ赤になって目を逸らした。|{a}「{b}、そっちはどう？｜{b}、そっちはどうだ？｜{b}、そちらはどうですか？」――{a}は息を弾ませながら、{h}の肩越しに楽しそうに声をかけた。'),
shy:L('{a}は、{h}の向こうにいる{b}と目が合いそうになって、慌てて顔を伏せた。|{a}「……{b}、こっち、見ないで｜……{b}、こっちを見るな｜……{b}、こちらを見ないでください」――消え入りそうな声だった。{b}は黙って、{h}のほうへ顔を向けた。'),
polite:L('{a}は{h}越しに、{b}へ小さく会釈をした。こんなときでも、その律儀さは崩れなかった。|{a}「{b}、先にごめんね｜{b}、先に失礼する｜{b}、お先に失礼します」――{a}は律儀にそう断ってから、{h}のほうへ向き直った。')
};
