var eff=function(kk){return mixAny&&kk==='m'?'n':kk;};
var fk=eff(fk0),fc=eff(fc0),rr={k:m.k,c:m.c,u:m.u},rng=ctx.rng,mm=fk0==='m'&&fc0==='m';
var stAll=ctx.flags.trioRV||(ctx.flags.trioRV={}),key=m.k.i+'-'+m.c.i+'-'+m.u.i;
