var rnd=rngOf(S);
var cands=[];
g.forEach(function(d){
var tr=g.filter(function(c){return c!==d;});
var pl=Q.trioPlan(tr[0],tr[1],tr[2],o.ok?{ok:o.ok}:undefined);
if(!pl)return;
var sp=X.shapeOf(S,tr,pl);
if(!sp)return;
var E=edgesOf(sp),F=E[Math.min(1,E.length-1)],z=tr.filter(function(c){return F.indexOf(c)<0;})[0];
var par= !!z&&okP(z,d);
cands.push({d:d,tr:tr,pl:pl,sp:sp,E:E,F:F,z:z,par:par,v:(par?2:0)+(o.lead&&o.lead!==d?1:0)});
});
if(!cands.length)return'';
var top=Math.max.apply(null,cands.map(function(c){return c.v;}));
cands=cands.filter(function(c){return c.v===top;});
var K=cands[Math.floor(rnd()*cands.length)];
var sp=K.sp,d=K.d,z=K.z,F=K.F,x=F[0],y=F[1];
var p2=K.par?Q.order(z,d,[z,d]):null,T=p2&&p2[0],B=p2&&p2[1],k2=p2?X.edgeKind(T,B):'';
var info={model:p2?'par':'watch',p:sp.p,k2:k2,ord:''};
var C=X.begin(S,sp,Object.assign({},o,{apart:X.apartOf(K.tr,K.pl),first:true,more:[d],four:info,posePre:true,range:RANGE4,qmax:QMAX4,noXch:p2?STG:['after'],endE:p2?[F,p2]:null}));
if(!C)return'';
var len=C.len,qb=QB[len]||QB.thick,pick=function(a){return C.pk(a);};
var E0=K.E[0],a=E0[0],b=E0[1],c=K.tr.filter(function(q){return q!==a&&q!==b;})[0];
