var text=parts.join('').replace(/\{wA\}/g,WORD_A[w]).replace(/\{wB\}/g,WORD_B[w]).replace(/\{w\}/g,WORD[w]).replace(/\{a\}/g,x.name).replace(/\{b\}/g,y.name);
