if(o.need&& !NEED[o.need](ctx,a,b,r))return false;
var q=rmOf(ctx,a,b);
if(q.last===ctx.stepIndex)return false;
if(q.at[o.k]!=null&&ctx.stepIndex-q.at[o.k]<GAP)return false;
