var CLOCK_LINE=L('{a}「……時間、ないね｜……時間がないな｜……時間、ないですね」|{a}「……あと、どれくらい？｜……あと、どれくらいだ？｜……あと、どれくらいですか？」|{b}「……分かってる｜……分かっている｜……分かっています」');
