if(!foes.length)foes=P.filter(function(k){return k!==v&& !spare(ctx,v,k);});
var k=foes.sort(function(x,y){return(hate(ctx,y,v).v+ctx.power(y)/200)-(hate(ctx,x,v).v+ctx.power(x)/200);})[0];
